/* 
 * LPC2148 SmartX Board - UART0 Hello World 
 * Sends "Hello LPC2148" to the Serial Monitor. 
 * Uses register-level UART0 at 9600 baud. 
 */ 

#include <LPC214x.h>

// Simple delay function in milliseconds (Assumes 60MHz CCLK)
void delay_ms(unsigned int ms) {
    unsigned int i, j;
    for (i = 0; i < ms; i++) {
        for (j = 0; j < 7500; j++); 
    }
}

void UART0_Init(unsigned int baud) {
    unsigned int divisor = 15000000 / (16 * baud); // Assumes PCLK = 15MHz

    // Configure P0.0 as TXD0 and P0.1 as RXD0
    PINSEL0 |= (1 << 1) | (1 << 3);
    PINSEL0 &= ~((1 << 0) | (1 << 2));

    U0LCR = 0x83;                  // Enable DLAB, 8-bit character length
    U0DLL = divisor & 0xFF;        // Lower byte of divisor
    U0DLM = (divisor >> 8) & 0xFF; // Upper byte of divisor
    U0LCR = 0x03;                  // Disable DLAB, keep 8-bit length
    U0FCR = 0x07;                  // Enable and clear FIFO
}

void UART0_SendChar(unsigned char ch) {
    while (!(U0LSR & 0x20));       // Wait until THR is empty (THRE bit)
    U0THR = ch;                    // Transmit character
}

// Optimized string printing function
void UART0_SendString(char *str) {
    while (*str) {                 // Loop until the null terminator ('\0') is reached
        UART0_SendChar(*str++);    // Send the current character and move pointer to next
    }
}

int main(void) {
    // String literal handles the null terminator automatically
    char msg[] = "Hello LPC2148\r\n"; 

    UART0_Init(9600);
    UART0_SendString(msg);

    while (1) {
        // Echo back received characters
        if (U0LSR & 0x01) {        // Check RDR bit (Receiver Data Ready)
            unsigned char ch = U0RBR;
            UART0_SendChar(ch);
        }
        delay_ms(10);
    }
}
